    spd=-0.4 if abs(h)<35 and min(dfr,dfl,drr,drl)>1.0 else -0.3
    if t-lastprint>2.0:
        lastprint=t
        print('t%.1f rev h%.0f hd%.0f b%.0f bd%.0f sc%.2f fr%.2f fl%.2f rr%.2f rl%.2f st%.0f'%(t,h,hdes,beta,bdes,best,dfr,dfl,drr,drl,steer))
