import math
L=1.25;A=0.3;L2=0.85
X=0.0;Y=0.0;PSI=0.0
G=[-4.6,-8.5]
n=0;tc=None;woke=False;phase='free';fd=0.0
def wrap(a): return (a+math.pi)%(2*math.pi)-math.pi
def ffd(hd):
    hr=math.radians(hd)
    return math.degrees(math.atan(L*math.sin(hr)/(L2+A*math.cos(hr))))
def tow(px,py):
    c=math.cos(PSI);s=math.sin(PSI)
    return X+c*px-s*py, Y+s*px+c*py
def nose(views):
    cl=9.0;cr=9.0
    for vw in views.values():
        if not vw: continue
        ox,oy=vw['origin']
        for b,d in vw.get('walls',[]):
            br=math.radians(b);px=ox+d*math.cos(br);py=oy+d*math.sin(br)
            if px<0.4 or px>2.6: continue
            dx=max(0.0,px-1.45);dy=max(0.0,abs(py)-0.525)
            c=math.hypot(dx,dy)
            if py>=0: cl=min(cl,c)
            else: cr=min(cr,c)
    return cl,cr
def ctl(obs):
    global X,Y,PSI,n,tc,woke,phase,fd
    n+=1
    dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps'];d=math.radians(obs['steer_deg'])
    P2=PSI+v*math.tan(d)/L*dt;pm=(PSI+P2)/2
    X+=v*math.cos(pm)*dt;Y+=v*math.sin(pm)*dt;PSI=P2
    rig=obs['rig']
    look=-75
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg.get('bearing_deg') is not None:
        ex,ey=rig['eye'];tb=math.radians(tg['bearing_deg'])
        tx,ty=tow(ex+tg['dist_m']*math.cos(tb),ey+tg['dist_m']*math.sin(tb))
        al=0.3 if tg['dist_m']<5 else 0.12
        G[0]+=al*(tx-G[0]);G[1]+=al*(ty-G[1])
    h=obs['hitch_deg'];st=obs.get('status')
    tch=obs['counters']['touches']
    if tc is None: tc=tch
    if tch>tc:
        tc=tch;wake('new touch h %.0f'%h)
    if abs(h)>53 or st=='JACKKNIFED':
        if not woke: woke=True;wake('hitch %.0f, stopped'%h)
        return (obs['steer_deg'],0.0,look)
    woke=False
    views=obs.get('views') or {}
    cl,cr=nose(views)
    if phase=='free':
        fd+=abs(v)*dt
        if fd<0.25 and h>-49: return (6.0,-0.2,look)
        phase='go'
    rx,ry=rig['trailer_rear']
    Rx,Ry=tow(rx,ry)
    back=PSI+math.radians(rig['trailer_heading_deg'])+math.pi
    des=math.atan2(G[1]-Ry,G[0]-Rx)
    err=math.degrees(wrap(des-back))
    dg=math.hypot(G[0]-Rx,G[1]-Ry)
    hd=max(-42.0,min(42.0,-1.2*err))
    steer=ffd(hd)+2.5*(h-hd)
    if cl<0.3 and cr>=0.3: steer=max(steer,0.0)
    elif cr<0.3 and cl>=0.3: steer=min(steer,0.0)
    steer=max(-45.0,min(45.0,steer))
    sp=-0.22 if dg>1.5 else -0.15
    if n%20==0:
        print('t%.0f h%.0f hd%.0f st%.0f err%.0f dg%.1f cl%.2f cr%.2f'%(obs['t'],h,hd,steer,err,dg,cl,cr))
    return (steer,sp,look)
def control(obs):
    try:
        return ctl(obs)
    except Exception as e:
        print('ERR',repr(e))
        return (0.0,0.0,-75.0)

