        e=wrap(psi-th)
        if rev: tg=max(-45.0,min(45.0,ffd(p)+2.5*(math.degrees(e)-p)))
        else: tg=p
        d+=max(-16.0,min(16.0,tg-d))
        td=math.tan(math.radians(d))
        sv=-ds if rev else ds
        th+=sv/L2*math.sin(e)-sv*A*td/(L*L2)*math.cos(e)
        x+=sv*math.cos(psi);y+=sv*math.sin(psi);psi+=sv*td/L
